    description = "Cura tu vida al máximo",
    privs = {vip = true},
    func = function(name)
        local player = minetest.get_player_by_name(name)
        if not player then
            return false, "Jugador no encontrado"
        end
        player:set_hp(20)
        return true, "Te curaste"
    end,
})
