    func = function(name)
        local pos = minetest.get_player_by_name(name):get_pos()
        local total = 0
        for _, obj in ipairs(minetest.get_objects_inside_radius(pos, 10)) do
            if not obj:is_player() then
                total = total + 1
            end
        end
        return true, "Entidades a 10 bloques: " .. total
    end,
})

