local niveles = {
    {nombre = "madera", tiempo = 3.0, usos = 10, nivel = 1},
    {nombre = "piedra", tiempo = 2.0, usos = 30, nivel = 2},
    {nombre = "metal", tiempo = 1.0, usos = 80, nivel = 3},
}

for _, m in ipairs(niveles) do
    minetest.register_tool("items:pico_" .. m.nombre, {
        description = "Pico de " .. m.nombre,
        inventory_image = "items_pico_" .. m.nombre .. ".png",
        tool_capabilities = {
            full_punch_interval = 1.0,
            max_drop_level = m.nivel,
            groupcaps = {
                cracky = {times = {[1] = m.tiempo * 2, [2] = m.tiempo, [3] = m.tiempo / 2}, uses = m.usos, maxlevel = m.nivel},
            },
        },
    })
end
